mapper.select:
SELECT uc.id AS couponId, uc.coupon_code, uc.coupon_status AS userCouponStatus, uc.valid_start_time, uc.valid_end_time, uc.created_time AS receivedTime, ct.name, ct.type, ct.summary, ct.coupon_status, ct.discount_rate, ct.discount_amount
FROM coupon_templates AS ct JOIN user_coupons AS uc ON ct.id = uc.template_id
WHERE uc.is_deleted = 0 AND
uc.id = #{couponId}
uc.coupon_code = #{couponCode}

SELECT uc.id AS couponId, uc.coupon_status, uc.valid_start_time, uc.valid_end_time, ct.name, ct.summary, ct.min_spend_amount, ct.max_deductible_amount, ct.id AS couponTemplateId, ct.discount_rate, ct.discount_amount, ct.scope, ct.type
FROM coupon_templates AS ct JOIN user_coupons AS uc ON ct.id = uc.template_id WHERE uc.id IN
#{id}
